/** Operations present in the API Definition but omitted by this
 * generation's operation cap. Kept deliberately small: enough for honest
 * discovery and PLAN_LIMIT errors, never enough to call an absent method. */
export type OmittedOpSpec = Pick<OpSpec,
  "resource" | "method" | "command" | "commandAlias" | "tool" | "httpMethod" |
  "path" | "summary" | "description" | "toolDescription" | "paginated" |
  "select" | "safety" | "auth" | "params" | "inputSchema"
>;

